import json

workspaces = {
    'api': {'root': '~/api', 'open': ['main.py'], 'layout': 'split-v'},
    'docs': {'root': '~/docs', 'open': ['index.md'], 'layout': 'single'},
}
current = 'api'

def switch(name):
    global current
    saved = json.dumps(workspaces[current])  # save current context
    current = name
    return 'saved %s (%d bytes); loaded %s' % (workspaces['api']['root'], len(saved), name)

print(switch('docs'))
print('context switch: seconds, not the 20 minutes of "where was I"')

# stash: named snapshots of uncommitted work
stashes = {}
workdir = {'main.py': 'v2-edit'}

def stash(name):
    stashes[name] = dict(workdir)
    workdir.clear()
    return 'stashed "%s" (%d files)' % (name, len(stashes[name]))

def pop(name):
    workdir.update(stashes.pop(name))
    return 'restored "%s"' % name

print(stash('wip-api-fix'))
print('workdir:', workdir, '(clean)')
print(pop('wip-api-fix'), '->', workdir)
print('auto-stash on workspace switch: WIP never lost between contexts')

