import json, os

state = {'workspaces': ['api', 'docs'], 'active': 'api', 'dirty': {'main.py': 'v2'}}

def persist(path='/tmp/ws-session.json'):
    tmp = path + '.tmp'
    with open(tmp, 'w') as f:
        json.dump(state, f)
    os.replace(tmp, path)  # atomic: crash never leaves half a session
    return 'persisted atomically (%d bytes)' % os.path.getsize(path)

print(persist())
print('debounced snapshots; atomic replace; staged restore on launch')

