# workspace events for automation; scoped storage per workspace
listeners = {'onSwitch': []}
storage = {}

def on_switch(fn):
    listeners['onSwitch'].append(fn)

def switch_ws(name):
    storage.setdefault(name, {})
    for fn in listeners['onSwitch']:
        fn(name, storage[name])

on_switch(lambda n, s: s.update(visits=s.get('visits', 0) + 1))
switch_ws('api'); switch_ws('api')
print('workspace storage:', storage)
print('plugins automate on switch; storage scoped (no cross-workspace leaks)')

import random
random.seed(2)

# fuzz switch/stash; invariant: exactly one active workspace, stashes intact
active, stashes, saved = 'a', {}, {}

def check():
    assert isinstance(active, str) and active
    assert all(isinstance(v, dict) for v in stashes.values())

for _ in range(300):
    op = random.random()
    if op < 0.5:
        saved[active] = {'n': 1}; active = random.choice(['a', 'b', 'c'])
    elif op < 0.8:
        stashes['s%d' % len(stashes)] = {'w': active}
    else:
        if stashes:
            stashes.pop(random.choice(list(stashes)))
    check()
print('300 random switch/stash ops: state invariants held')
print('kill -9 mid-switch must also leave a consistent state (test it)')
